// ─── File: src/test/java/com/bank/threadlocal/ThreadLocalLeakTest.java ───
package com.bank.threadlocal;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ThreadLocalLeakTest {

    static final ThreadLocal<String> userContext = new ThreadLocal<>();

    // ═══ DATA LEAK: next task sees previous task's data ═══
    @Test
    void dataLeak_withoutRemove() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);  // 1 thread!
        AtomicReference<String> leakedUser = new AtomicReference<>();
        CountDownLatch done = new CountDownLatch(2);

        // Task 1: sets but doesn't remove!
        pool.submit(() -> {
            userContext.set("Rajesh");
            // NO remove()!
            done.countDown();
        });

        Thread.sleep(100);  // ensure task 1 finishes first

        // Task 2: reads — gets Rajesh's data!
        pool.submit(() -> {
            leakedUser.set(userContext.get());  // "Rajesh"! LEAKED!
            done.countDown();
        });

        done.await(5, TimeUnit.SECONDS);
        assertThat(leakedUser.get()).isEqualTo("Rajesh");  // DATA LEAK!
        pool.shutdown();
    }

    // ═══ FIX: remove() in finally — no leak ═══
    @Test
    void noLeak_withRemove() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        AtomicReference<String> nextTaskUser = new AtomicReference<>();
        CountDownLatch done = new CountDownLatch(2);

        // Task 1: sets AND removes!
        pool.submit(() -> {
            try {
                userContext.set("Rajesh");
                // process...
            } finally {
                userContext.remove();  // CLEAN!
            }
            done.countDown();
        });

        Thread.sleep(100);

        // Task 2: reads — gets null! Clean!
        pool.submit(() -> {
            nextTaskUser.set(userContext.get());
            done.countDown();
        });

        done.await(5, TimeUnit.SECONDS);
        assertThat(nextTaskUser.get()).isNull();  // CLEAN! No leak!
        pool.shutdown();
    }

    // ═══ SAFE PATTERN: wrapper that auto-cleans ═══
    static <T> Runnable withContext(String user, Runnable task) {
        return () -> {
            try {
                userContext.set(user);
                task.run();
            } finally {
                userContext.remove();  // always cleanup!
            }
        };
    }

    @Test
    void safePattern_autoClean() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        AtomicReference<String> afterClean = new AtomicReference<>();
        CountDownLatch done = new CountDownLatch(2);

        pool.submit(withContext("Rajesh", () -> {
            assertThat(userContext.get()).isEqualTo("Rajesh");
            done.countDown();
        }));

        Thread.sleep(100);

        pool.submit(() -> {
            afterClean.set(userContext.get());
            done.countDown();
        });

        done.await(5, TimeUnit.SECONDS);
        assertThat(afterClean.get()).isNull();  // auto-cleaned!
        pool.shutdown();
    }
}
